     1	/*
     2	 * Flux Controller — mDNS advertisement
     3	 *
     4	 * Owns all mDNS registrations for the Flux controller.  See flux_mdns.h for
     5	 * a description of which services are advertised, when, and why.
     6	 *
     7	 * Note: _meshcop._udp is registered by esp_openthread_border_router_init(),
     8	 * not here.  This module only patches the vendor/model TXT records on it.
     9	 */
    10	
    11	#include "flux_mdns.h"
    12	#include "flux_config.h"       /* FLUX_BACKBONE_IFKEY */
    13	
    14	#include <mdns.h>
    15	#include <esp_mac.h>
    16	#include <esp_log.h>
    17	#include <esp_netif.h>
    18	#include <freertos/FreeRTOS.h>
    19	#include <freertos/task.h>
    20	#include <stdio.h>
    21	#include <string.h>
    22	
    23	static const char *TAG = "flux_mdns";
    24	
    25	#define FLUX_VERSION       "0.1.0"
    26	#define FLUX_MDNS_SERVICE  "_fluxhub"
    27	#define FLUX_MDNS_PROTO    "_tcp"
    28	#define FLUX_MDNS_PORT     5684      /* CoAP/DTLS */
    29	
    30	/* ── _fluxhub._tcp ───────────────────────────────────────────────────────── */
    31	
    32	esp_err_t flux_mdns_on_eth_ip(void)
    33	{
    34	    static bool started = false;
    35	    if (started) return ESP_OK;
    36	    started = true;
    37	
    38	    /* Hostname: flux-controller-<last 3 bytes of ETH MAC>.local */
    39	    uint8_t mac[6];
    40	    esp_read_mac(mac, ESP_MAC_ETH);
    41	
    42	    char hostname[32];
    43	    snprintf(hostname, sizeof(hostname), "flux-controller-%02x%02x%02x",
    44	             mac[3], mac[4], mac[5]);
    45	
