void flux_otbr_init(void)
{
    /* eventfd for the OpenThread netif glue: netif + task queue + radio spinel +
     * BR discovery + infra_if need 5+. */
    esp_vfs_eventfd_config_t eventfd_config = { .max_fds = 6 };
    ESP_ERROR_CHECK(esp_vfs_eventfd_register(&eventfd_config));

    /* Graceful RCP-failure handler (the default asserts): reboot so the
     * c6_flasher can recover next boot, bounded by the RTC counter, then run
     * without Thread. Register BEFORE Matter starts the OT stack. */
    esp_openthread_register_rcp_failure_handler([]() {
        if (s_rcp_fail_reboots < RCP_MAX_FAIL_REBOOTS) {
            s_rcp_fail_reboots++;
            ESP_LOGE(TAG, "RCP co-processor reset failed — rebooting (%u/%d)",
                     (unsigned)s_rcp_fail_reboots, RCP_MAX_FAIL_REBOOTS);
            esp_restart();
        }
        ESP_LOGE(TAG, "RCP still down after %d reboots — continuing WITHOUT Thread "
                 "(check C6 fly wires; power-cycle to retry)", RCP_MAX_FAIL_REBOOTS);
    });

    /* OT radio config (spinel UART to the C6) before esp_matter::start(). */
    esp_openthread_platform_config_t ot_config = {
