CHIP_ERROR ChipDnssdBrowse(const char * type, DnssdServiceProtocol protocol, chip::Inet::IPAddressType addressType,
                           chip::Inet::InterfaceId interface, DnssdBrowseCallback callback, void * context,
                           intptr_t * browseIdentifier)
{
    // FLUX LOCAL PATCH — see flux-controller docs/adr/0014.
    // Dispatch to ONE backend, not to every enabled one. On a Thread Border Router
    // with an Ethernet backbone both conditions below are true, so the original
    // code started two browses sharing a single callback and context, while CHIP's
    // upper layers assume exactly one completion. Prefer the infrastructure (mDNS)
    // path when it exists and fall back to Thread only when it does not.
    bool usedInfraBackend = false;
#if CHIP_DEVICE_CONFIG_ENABLE_WIFI || CHIP_DEVICE_CONFIG_ENABLE_ETHERNET
    if (ConnectivityMgr().IsWiFiStationProvisioned() || ESP32Utils::HasIPv6LinkLocalAddress(ESP32Utils::kDefaultEthernetNetifKey))
    {
        ReturnErrorOnFailure(EspDnssdBrowse(type, protocol, addressType, interface, callback, context, browseIdentifier));
        usedInfraBackend = true;
    }
#endif
#if CHIP_DEVICE_CONFIG_ENABLE_THREAD && CHIP_DEVICE_CONFIG_ENABLE_THREAD_SRP_CLIENT && CHIP_DEVICE_CONFIG_ENABLE_THREAD_DNS_CLIENT
    if (!usedInfraBackend && ConnectivityMgr().IsThreadProvisioned())
    {
        ReturnErrorOnFailure(OpenThreadDnssdBrowse(type, protocol, addressType, interface, callback, context, browseIdentifier));
    }
#endif
    (void) usedInfraBackend;
    return CHIP_NO_ERROR;
}

