size_t flux_coap_energy_snapshot(flux_energy_sample_t *out, size_t max)
{
    if (!out || max == 0 || s_attr_cache == NULL) return 0;
    size_t n = 0;
    cache_lock();
    for (size_t i = 0; i < s_attr_cache_n && n < max; i++) {
        const node_cache_t *c = &s_attr_cache[i];
        flux_energy_sample_t s;
        memset(&s, 0, sizeof(s));
        s.node_id  = c->node_id;
        s.kind     = c->kind;
        s.endpoint = c->endpoint;
        bool any = false;
        for (size_t j = 0; j < c->n_attrs; j++) {
            const cached_attr_t *a = &c->attrs[j];
            if      (strcmp(a->key, "activePower") == 0)                 { s.active_power_mw   = a->lv; s.has_power   = true; any = true; }
            else if (strcmp(a->key, "voltage") == 0)                     { s.voltage_mv        = a->lv; s.has_voltage = true; any = true; }
            else if (strcmp(a->key, "activeCurrent") == 0)               { s.current_ma        = a->lv; s.has_current = true; any = true; }
            else if (strcmp(a->key, "cumulativeEnergyMwh") == 0)         { s.energy_import_mwh = a->lv; s.has_import  = true; any = true; }
            else if (strcmp(a->key, "cumulativeEnergyExportedMwh") == 0) { s.energy_export_mwh = a->lv; s.has_export  = true; any = true; }
            else if (strcmp(a->key, "batPercentRaw") == 0)               { s.soc_pct          = a->iv / 2; s.has_soc  = true; any = true; }  /* half-% → % */
        }
        if (any) out[n++] = s;
    }
    cache_unlock();
    return n;
}

