uint8_t flux_coap_cache_get_connectivity(uint8_t kind, uint64_t node_id)
{
    if (s_attr_cache == NULL) return flux_ConnectivityState_CONNECTIVITY_UNKNOWN;
    for (size_t i = 0; i < s_attr_cache_n; i++) {
        if (s_attr_cache[i].node_id == node_id && s_attr_cache[i].kind == kind
            && s_attr_cache[i].endpoint == 0)
            return s_attr_cache[i].connectivity;
