}

/* Whether the DEVICE (kind, node_id, endpoint) is reachable. The node's session
 * must be up, and a bridged child must not have reported Reachable=false — the
 * bridge answering says nothing about the lamp behind it. A child that has not
 * reported Reachable yet follows its bridge. CoAP-task-only, like the getter
 * above. */
bool flux_coap_cache_is_reachable(uint8_t kind, uint64_t node_id, uint16_t endpoint)
{
    if (flux_coap_cache_get_connectivity(kind, node_id)
        != REDACTED)
        return false;
    if (endpoint == 0 || s_attr_cache == NULL) return true;
    for (size_t i = 0; i < s_attr_cache_n; i++) {
        const node_cache_t *c = &s_attr_cache[i];
        if (c->node_id != node_id || c->kind != kind || c->endpoint != endpoint)
            continue;
        for (size_t j = 0; j < c->n_attrs; j++)
            if (c->attrs[j].which == 1 && strcmp(c->attrs[j].key, "reachable") == 0)
                return c->attrs[j].bv;
        break;
    }
    return true;
}

