/* ── Power adjustment (Matter Device Energy Management, PA feature) ──────────
 *
 * A profile whose device can be told to charge/discharge at a set power exposes
 * it in the shape of the Matter DEM cluster (0x0098): a power setpoint in mW,
 * signed like activePower (+ = consuming/charging, − = generating/discharging),
 * held for a bounded duration. The hold itself — its timer, re-assertion and
 * release — lives in the poll task; a profile only applies or releases. */
typedef struct {
    int64_t  min_power_mw;     /* most negative setpoint (max discharge) */
    int64_t  max_power_mw;     /* most positive setpoint (max charge)    */
    uint32_t max_duration_s;   /* longest hold the controller will accept */
} flux_modbus_power_cap_t;

/* True if profile `id` supports power adjustment; fills *cap when non-NULL. */
bool flux_modbus_profile_power_cap(flux_modbus_profile_id_t id,
                                   flux_modbus_power_cap_t *cap);

/* Put the device under external control at `power_mw` (already range-checked
 * against the cap). Idempotent — the poll task calls it again on every poll to
 * keep the setpoint asserted. Reads back what took effect: a device that
 * acknowledges and ignores the write is a failure, not success. */
esp_err_t flux_modbus_profile_power_apply(flux_modbus_profile_ctx_t *ctx,
                                          flux_modbus_handle_t h, int64_t power_mw);

/* Hand control back to the device's own operating mode. */
esp_err_t flux_modbus_profile_power_release(flux_modbus_profile_ctx_t *ctx,
                                            flux_modbus_handle_t h);

#ifdef __cplusplus
}
