esp_err_t flux_sunspec_read_curtail(flux_modbus_handle_t h,
                                    const flux_sunspec_ctx_t *ctx,
                                    flux_sunspec_curtail_t *out)
{
    if (!h || !ctx || !out) return ESP_ERR_INVALID_ARG;
    memset(out, 0, sizeof(*out));

    const flux_sunspec_model_loc_t *c = &ctx->ctl.controls;
    if (!c->start) return ESP_ERR_NOT_FOUND;
    if (c->len < CONTROLS_MIN_LEN) {
        ESP_LOGW(TAG, "model 123 too short (len %u)", c->len);
        return ESP_ERR_NOT_FOUND;
    }

    uint16_t n = c->len < MODEL_BUF_REGS ? c->len : MODEL_BUF_REGS;
    uint16_t buf[MODEL_BUF_REGS];
    esp_err_t err = flux_modbus_read_holding(h, c->start, n, buf);
    if (err != ESP_OK) return err;

    out->present    = true;
    out->enabled    = buf[OFF_WMAXLIM_ENA] != NA_U16 && buf[OFF_WMAXLIM_ENA] != 0;
    out->rvrt_tms_s = buf[OFF_WMAXLIMPCT_RVRT] == NA_U16 ? 0 : buf[OFF_WMAXLIMPCT_RVRT];
    out->rmp_tms_s  = buf[OFF_WMAXLIMPCT_RMP]  == NA_U16 ? 0 : buf[OFF_WMAXLIMPCT_RMP];
