new = r'''/* ── Curtailment writes ───────────────────────────────────────────────────── */

/* Encodes `v` for a register whose scale factor is `sf`: the inverse of
 * apply_sf. SF is negative for fractional units (sf=-2 means hundredths), so a
 * 50 % limit with sf=-2 goes on the wire as 5000. */
static uint16_t encode_sf(double v, int16_t sf)
{
    double scaled = v;
    for (int i = 0; i < -sf; i++) scaled *= 10.0;
    for (int i = 0; i < sf; i++)  scaled /= 10.0;
    if (scaled < 0) scaled = 0;
    if (scaled > 65535.0) scaled = 65535.0;
    return (uint16_t)(scaled + 0.5);
}

static esp_err_t curtail_write_block(flux_modbus_handle_t h,
                                     const flux_sunspec_ctx_t *ctx,
                                     bool enable, double limit_pct,
                                     uint16_t revert_s)
{
    if (!h || !ctx) return ESP_ERR_INVALID_ARG;
    const flux_sunspec_model_loc_t *c = &ctx->ctl.controls;
    if (!c->start || c->len < CONTROLS_MIN_LEN) return ESP_ERR_NOT_SUPPORTED;

    /* The scale factor lives at the far end of the model, outside the block we
     * write, so it has to be read before the value can be encoded. */
    uint16_t n = c->len < MODEL_BUF_REGS ? c->len : MODEL_BUF_REGS;
    uint16_t buf[MODEL_BUF_REGS];
    esp_err_t err = flux_modbus_read_holding(h, c->start, n, buf);
    if (err != ESP_OK) return err;
    if (buf[OFF_WMAXLIMPCT] == NA_U16) return ESP_ERR_NOT_SUPPORTED;

    const int16_t sf = (int16_t)buf[OFF_WMAXLIMPCT_SF];
    if (limit_pct < 0)   limit_pct = 0;
    if (limit_pct > 100) limit_pct = 100;

    /* Registers 3..7, in model order: setpoint, window, revert, ramp, enable.
     * Window and ramp stay 0 — immediate, no averaging — because a cap that
     * eases in over a ramp is not a cap during the ramp. */
    uint16_t out[5] = {
        encode_sf(limit_pct, sf),
        0,
        revert_s,
        0,
        enable ? 1 : 0,
    };
    err = flux_modbus_write_holding(h, (uint16_t)(c->start + OFF_WMAXLIMPCT), 5, out);
    if (err != ESP_OK) return err;

    /* Read back: several inverters ACK a write to a register they do not
     * implement. Compare the enable flag and the setpoint we asked for. */
    err = flux_modbus_read_holding(h, c->start, n, buf);
    if (err != ESP_OK) return err;
    const bool ena_now = buf[OFF_WMAXLIM_ENA] != NA_U16 && buf[OFF_WMAXLIM_ENA] != 0;
    const double pct_now = apply_sf((double)buf[OFF_WMAXLIMPCT], sf);
    if (ena_now != enable) {
        ESP_LOGW(TAG, "curtail write ignored: asked ena=%d, reads %d",
                 (int)enable, (int)ena_now);
        return ESP_ERR_INVALID_RESPONSE;
    }
    if (enable && (pct_now < limit_pct - 1.0 || pct_now > limit_pct + 1.0)) {
        ESP_LOGW(TAG, "curtail write ignored: asked %.1f%%, reads %.1f%%",
                 limit_pct, pct_now);
        return ESP_ERR_INVALID_RESPONSE;
    }
    ESP_LOGI(TAG, "curtail set: ena=%d WMaxLimPct=%.1f%% rvrt=%us",
             (int)ena_now, pct_now, revert_s);
    return ESP_OK;
}

esp_err_t flux_sunspec_write_curtail(flux_modbus_handle_t h,
                                     const flux_sunspec_ctx_t *ctx,
                                     double limit_pct, uint16_t revert_s)
{
    return curtail_write_block(h, ctx, true, limit_pct, revert_s);
}

esp_err_t flux_sunspec_clear_curtail(flux_modbus_handle_t h,
                                     const flux_sunspec_ctx_t *ctx)
{
    /* 100 % alongside the disable: if a firmware honours the setpoint even with
     * the enable clear, the stored value is the harmless one. */
    return curtail_write_block(h, ctx, false, 100.0, 0);
}

