     * "no limit" rather than rejected, so a caller sweeping a setpoint through
     * zero does not get an error at the crossing. */
    if (power_mw >= 0) return flux_sunspec_clear_curtail(h, &ctx->sunspec);

    const double w_max = ctx->sunspec_w_max;
    if (w_max <= 0) {
        /* Without WMax a watt figure cannot become a percentage, and guessing
         * the denominator would silently curtail to the wrong level. */
        ESP_LOGW(TAG, "curtail: WMax unknown — audit has not run yet");
        return ESP_ERR_INVALID_STATE;
