    const double want_w = (double)(-power_mw) / 1000.0;
    double pct = want_w / w_max * 100.0;
    if (pct > 100.0) pct = 100.0;   /* asking for more than nameplate = no cap */
    if (pct < 0.0)   pct = 0.0;
    return flux_sunspec_write_curtail(h, &ctx->sunspec, pct, SUNSPEC_REVERT_S);
