s=open(p).read()

anchor = "/* ── SunSpec curtailment as power adjustment ───"
new = r'''/* ── Victron GX: a battery request becomes a grid setpoint ───────────────────
 *
 * The GX has no battery-power setpoint. Its only control surface is ESS's
 * AcPowerSetpoint, which targets the GRID — "charge at 2 kW" and "import 2 kW"
 * are different requests, and conflating them would charge the wrong amount
 * whenever the house is drawing or the sun is up.
 *
 * They are related, though. At the AC bus
 *
 *     P_grid = P_load − P_pv + P_batt
 *
 * so moving the battery by ΔP moves the grid by the same ΔP whatever the load
 * and PV happen to be:
 *
 *     G_target = G_actual + (B_target − B_actual)
 *
 * Neither PV nor load appears, which is the point: both are unmeasured here and
 * both drift. power_apply() is re-called on every poll while a hold is active,
 * so the correction re-evaluates continuously and converges rather than
 * depending on one reading being right.
 *
 * Hub4Mode is the handover switch: 3 hands control to us, 1 gives it back. The
 * setpoint itself has NO expiry — the GX holds whatever it was last told — so
 * release() restoring mode 1 is the only thing standing between a crash and a
 * battery pinned at a setpoint. The poll task's hold timer calls release() when
 * the duration runs out, and ensure_internal_mode() on first poll puts the GX
 * back under its own ESS after a controller reboot.
 */
#define VICTRON_REG_GRID_L1     820     /* ac/Grid/Lx/Power, W, + = importing */
#define VICTRON_REG_BATT_POWER  842     /* W, + = charging */
#define VICTRON_REG_SETPOINT_L1 2700    /* Hub4 AcPowerSetpoint, W */
#define VICTRON_REG_HUB4_MODE   2902    /* 1 = ESS internal, 3 = external control */
#define VICTRON_HUB4_INTERNAL   1
#define VICTRON_HUB4_EXTERNAL   3
#define VICTRON_MAX_W           5000    /* conservative until the Multi is known */
#define VICTRON_MAX_HOLD_S      (4u * 3600u)

static esp_err_t victron_read_i16(flux_modbus_handle_t h, uint16_t reg, int32_t *out)
{
    uint16_t v;
    esp_err_t err = flux_modbus_read_holding(h, reg, 1, &v);
    if (err == ESP_OK) *out = (int16_t)v;
    return err;
}

static esp_err_t victron_set_mode(flux_modbus_handle_t h, uint16_t mode)
{
    int32_t now = 0;
    if (victron_read_i16(h, VICTRON_REG_HUB4_MODE, &now) == ESP_OK &&
        (uint16_t)now == mode)
        return ESP_OK;                      /* already there — do not churn NVS */
    return flux_modbus_write_single(h, VICTRON_REG_HUB4_MODE, mode);
}

static esp_err_t victron_power_apply(flux_modbus_handle_t h, int64_t power_mw)
{
    esp_err_t err = victron_set_mode(h, VICTRON_HUB4_EXTERNAL);
    if (err != ESP_OK) return err;

    int32_t g1 = 0, g2 = 0, g3 = 0, b_w = 0;
    uint16_t g[3];
    if ((err = flux_modbus_read_holding(h, VICTRON_REG_GRID_L1, 3, g)) != ESP_OK)
        return err;
    g1 = (int16_t)g[0]; g2 = (int16_t)g[1]; g3 = (int16_t)g[2];
    if ((err = victron_read_i16(h, VICTRON_REG_BATT_POWER, &b_w)) != ESP_OK)
        return err;

    const int32_t g_actual = g1 + g2 + g3;
    const int32_t b_target = (int32_t)(power_mw / 1000);
    int32_t g_target = g_actual + (b_target - b_w);
    if (g_target >  VICTRON_MAX_W) g_target =  VICTRON_MAX_W;
    if (g_target < -VICTRON_MAX_W) g_target = -VICTRON_MAX_W;

    /* The whole target goes on L1 and the other two phases are zeroed: with
     * phase compensation the system balances across phases and L1 carries the
     * total, which is the "cap on the sum" this house is wired for. A per-phase
     * split would need the limit expressed per phase, which it is not. */
    uint16_t sp[3] = { (uint16_t)(int16_t)g_target, 0, 0 };
    err = flux_modbus_write_holding(h, VICTRON_REG_SETPOINT_L1, 3, sp);
    if (err != ESP_OK) return err;

    ESP_LOGI(TAG, "victron: batt %ld W -> %ld W, grid %ld W -> setpoint %ld W",
             (long)b_w, (long)b_target, (long)g_actual, (long)g_target);
    return ESP_OK;
}

static esp_err_t victron_power_release(flux_modbus_handle_t h)
{
    /* Zero the setpoint BEFORE handing back, so a GX that keeps reading it
     * cannot act on a stale target in the gap. */
    uint16_t sp[3] = { 0, 0, 0 };
    (void)flux_modbus_write_holding(h, VICTRON_REG_SETPOINT_L1, 3, sp);
    return victron_set_mode(h, VICTRON_HUB4_INTERNAL);
}

