 * Small enough that overshoot past the ceiling is brief, large enough to reach
 * a couple of kilowatts within a minute. */
#define RAMP_W           200

/* Below this much export headroom there is nothing worth probing for. */
#define PROBE_HEADROOM_W 300

static bool s_holding_battery;

static void cycle(void)
{
    actuator_t grid, battery, pv;
    collect(&grid, &battery, &pv);

    /* No trustworthy grid reading means no basis for letting the inverter
     * exceed the safe limit. The snapshot already withholds stale values, so an
     * absent reading here means "not being measured", not "zero". */
    if (!grid.found) {
        if (s_state.armed) {
            ESP_LOGW(TAG, "no grid reading — falling back to the safe limit");
            s_state.faults++;
        }
        fall_back(&battery, &pv);
        s_holding_battery = false;
        return;
    }

    const int32_t export_w = grid.power_w < 0 ? -grid.power_w : 0;
    const int32_t ceiling  = FLUX_EXPORT_CAP_W - FLUX_EXPORT_CAP_MARGIN_W;
    const int32_t error    = export_w - ceiling;   /* > 0 = over the limit */

    s_state.grid_w   = grid.power_w;
    s_state.export_w = export_w;
    s_state.armed    = true;

    /* Is the inverter pinned against the limit we gave it? If so there may be
     * more sun than it is allowed to use, and the only way to find out is to
     * give the battery somewhere to put it. */
    const bool pinned = pv.found && s_state.pv_limit_w > 0 &&
                        pv.power_w >= s_state.pv_limit_w - 100;

    int32_t batt_target = 0;
    if (battery.found) {
        const int32_t charging = battery.power_w > 0 ? battery.power_w : 0;

        if (error > 0) {
            /* Over the limit: the battery takes the excess. Incremental, so it
             * converges without knowing the load or the sun. */
            batt_target = charging + error;
        } else if (pinned && -error > PROBE_HEADROOM_W) {
            /* Under the limit AND the inverter is clipped: there is headroom to
             * export and production being withheld. Ramp absorption up; each
             * watt the battery takes becomes a watt the inverter is allowed to
             * make next cycle. Saturation needs no detection — when the battery
             * stops taking more, the measured figure stops rising and the limit
             * stops with it.
             *
             * Without this the module cannot start: the inverter sits at the
             * safe limit, so no surplus ever appears, so the battery is never
             * asked to absorb, so the limit never rises. */
            const int32_t step = (-error) < RAMP_W ? (-error) : RAMP_W;
            batt_target = charging + step;
        } else if (charging > 0) {
            /* Headroom and nothing being withheld: ease off rather than hold.
             * The surplus is gone — a cloud, or a load that came on. */
            batt_target = charging + error;
            if (batt_target < 0) batt_target = 0;
        }

        if (batt_target <= ABSORB_FLOOR_W) {
            /* Hand the battery back to its own mode rather than pinning it at
             * zero. Holding it at 0 W would suppress the ordinary
             * self-consumption charging this module has no business touching. */
            if (s_holding_battery) {
                (void)flux_modbus_task_power_cancel(battery.node_id);
                s_holding_battery = false;
            }
            batt_target = 0;
        } else {
            (void)flux_modbus_task_power_adjust(battery.node_id,
                                                (int64_t)batt_target * 1000,
                                                BATTERY_HOLD_S);
            s_holding_battery = true;
        }
        s_state.battery_actual_w = battery.power_w;
    }
    s_state.battery_target_w = batt_target;

    /* The inverter may exceed the safe limit only by what the battery is
     * MEASURED to be absorbing — never by what it was asked to absorb. A
     * request the battery ignores must not unlock headroom. */
    if (pv.found) {
        const int32_t absorbed = (battery.found && battery.power_w > ABSORB_FLOOR_W)
                               ? battery.power_w : 0;
        const int32_t limit_w  = FLUX_EXPORT_CAP_BASE_W + absorbed;
        (void)flux_modbus_task_power_adjust(pv.node_id,
                                            -(int64_t)limit_w * 1000, PV_HOLD_S);
        s_state.pv_limit_w = limit_w;
        s_state.curtailing = pinned;
    }
}

