cd /home/tado/workspace/flux/flux-controller && python3 - <<'PYEOF'
p='firmware/main/energy/flux_export_cap.c'
s=open(p).read()

old_start = s.index("    int32_t batt_target = 0;\n    if (battery.found) {")
old_end = s.index("    s_state.battery_target_w = batt_target;")
new = """    const int64_t now_us = esp_timer_get_time();
    int32_t batt_target = s_batt_setpoint_w;
    if (battery.found) {
        /* The integrator works on what we COMMANDED, never on what we measured:
         * the device's reported power lags its setpoint by several cycles, and
         * feeding that lag back is what made the loop oscillate. */
        if (error > 0) {
            /* Over the limit: take the excess. */
            batt_target = s_batt_setpoint_w + error;
        } else if (pinned && -error > PROBE_HEADROOM_W) {
            /* Under the limit and the inverter is clipped: ramp up to find the
             * surplus. Each watt absorbed becomes a watt the inverter may make. */
            const int32_t step = (-error) < RAMP_W ? (-error) : RAMP_W;
            batt_target = s_batt_setpoint_w + step;
        } else if (-error < PROBE_STOP_W) {
            /* Close to the ceiling with nothing withheld — hold station rather
             * than hunting. Hysteresis against PROBE_HEADROOM_W so a grid
             * reading wandering either side of one threshold cannot make the
             * loop alternate between probing and backing off. */
        } else if (s_batt_setpoint_w > 0) {
            /* Real headroom and nothing being withheld: the surplus is gone. */
            batt_target = s_batt_setpoint_w + error;
        }
        if (batt_target < 0) batt_target = 0;

        if (batt_target <= ABSORB_FLOOR_W) {
            /* Hand the battery back only after it has had nothing to do for a
             * while. Releasing the instant the target dips put the device
             * through a cancel/apply cycle every few seconds. */
            if (s_holding_battery && ++s_batt_idle_cycles >= RELEASE_CYCLES) {
                (void)flux_modbus_task_power_cancel(battery.node_id);
                s_holding_battery  = false;
                s_batt_setpoint_w  = 0;
                s_batt_idle_cycles = 0;
            }
            batt_target = s_batt_setpoint_w;
        } else {
            s_batt_idle_cycles = 0;
            send_battery(battery.node_id, batt_target, now_us);
        }
        s_state.battery_actual_w = battery.power_w;
    }
"""
s = s[:old_start] + new + s[old_end:]

s = s.replace("""        (void)flux_modbus_task_power_adjust(pv.node_id,
                                            -(int64_t)limit_w * 1000, PV_HOLD_S);
        s_state.pv_limit_w = limit_w;""",
"""        send_pv_limit(pv.node_id, limit_w, now_us);
        s_state.pv_limit_w = limit_w;""", 1)

s = s.replace("""#define PROBE_HEADROOM_W 300""",
"""#define PROBE_HEADROOM_W 300

/* Stop probing before the threshold that starts it, so a grid reading drifting
 * across one number cannot make the loop oscillate. */
#define PROBE_STOP_W     150""", 1)

s = s.replace("""        fall_back(&battery, &pv);
        s_holding_battery = false;
        return;""",
"""        fall_back(&battery, &pv);
        s_holding_battery  = false;
        s_batt_setpoint_w  = 0;
        s_batt_idle_cycles = 0;
        s_pv_sent_limit_w  = 0;   /* force the safe limit to be re-sent */
        return;""", 1)
open(p,'w').write(s)
print('control loop stabilised')
