      _Tone.holding => const Color(0xFFE8C14A),
      _Tone.warn => const Color(0xFFE0894A),
    };

class _Headline extends StatelessWidget {
  const _Headline({required this.plan});
  final _Plan plan;

  @override
  Widget build(BuildContext context) {
    final c = _toneColor(context, plan.tone);
    return Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Container(
          width: 8, height: 8,
          margin: const EdgeInsets.only(top: 6, right: 9),
          decoration: BoxDecoration(color: c, shape: BoxShape.circle),
        ),
        Expanded(
          child: Text(plan.headline,
              style: Theme.of(context).textTheme.titleMedium?.copyWith(
                    height: 1.35, fontWeight: FontWeight.w500,
                  )),
        ),
      ],
    );
  }
}

class _EventRow extends StatelessWidget {
  const _EventRow({required this.event});
  final _Event event;

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    return Padding(
      padding: const EdgeInsets.only(bottom: 8),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          SizedBox(
            width: 92,
            child: Text(event.when,
                style: TextStyle(
                  fontFeatures: const [FontFeature.tabularFigures()],
                  fontSize: 12.5,
                  color: cs.onSurfaceVariant,
                )),
          ),
          Expanded(
            child: Text(event.text,
                style: TextStyle(
                  fontSize: 13.5,
                  height: 1.35,
                  color: event.tone == _Tone.ok
                      ? cs.onSurfaceVariant
                      : _toneColor(context, event.tone),
                )),
          ),
        ],
      ),
    );
  }
}

/// The one thing the app cannot work out for itself. Asked here, where it first
/// matters, rather than in a settings screen nobody visits.
class _AskForCap extends StatefulWidget {
  const _AskForCap({required this.onSet});
  final Future<void> Function(int?) onSet;

  @override
  State<_AskForCap> createState() => _AskForCapState();
}

class _AskForCapState extends State<_AskForCap> {
  final _c = TextEditingController();

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text('How much may you feed into the grid?',
            style: TextStyle(fontSize: 13, color: cs.onSurfaceVariant)),
        const SizedBox(height: 2),
        Text('Your grid operator sets this. Nothing on the network reports it.',
            style: TextStyle(fontSize: 12, color: cs.onSurfaceVariant)),
        const SizedBox(height: 8),
        Row(
          children: [
            SizedBox(
              width: 110,
              child: TextField(
                controller: _c,
                keyboardType: TextInputType.number,
                decoration: const InputDecoration(
                  isDense: true, suffixText: 'W', hintText: '11600',
                ),
              ),
            ),
            const SizedBox(width: 10),
            FilledButton.tonal(
              onPressed: () {
                final v = int.tryParse(_c.text.trim());
                if (v != null && v > 0) widget.onSet(v);
              },
              child: const Text('Set'),
            ),
          ],
        ),
      ],
    );
  }
}

