/*
 * flux_coap_solar — CoAP endpoints for the local PV production forecast.
 *
 *   GET  /solar/forecast → SolarForecast  (cached, site-modelled on-device)
 *   GET  /solar/config   → SolarConfig
 *   POST /solar/config   ← SolarConfig    (persisted; nudges a refresh)
 */
#include "flux_coap.h"
#include "flux_coap_internal.h"
#include "flux_solar.h"
#include "flux_solar_provider.h"
#include "flux.pb.h"
#include "pb_encode.h"
#include "pb_decode.h"

#include <coap3/coap.h>
#include <esp_log.h>
#include <stdlib.h>

static const char *TAG = "flux_coap_solar";

void hnd_solar_forecast_get(coap_resource_t *resource, coap_session_t *session,
                            const coap_pdu_t *request, const coap_string_t *query,
                            coap_pdu_t *response)
{
    (void)query;
    flux_SolarForecast fc = flux_SolarForecast_init_zero;
    /* NOT_FOUND (nothing fetched yet) → return an empty-but-valid message so the
     * app renders "no data" without special-casing an error, as /prices does. */
    flux_solar_get_forecast(&fc);

    uint8_t *buf = malloc(flux_SolarForecast_size);
    if (!buf) { coap_pdu_set_code(response, COAP_RESPONSE_CODE_INTERNAL_ERROR); return; }
    pb_ostream_t os = pb_ostream_from_buffer(buf, flux_SolarForecast_size);
    if (!pb_encode(&os, flux_SolarForecast_fields, &fc)) {
        free(buf);
        coap_pdu_set_code(response, COAP_RESPONSE_CODE_INTERNAL_ERROR);
        return;
    }
    coap_send_proto(resource, session, request, response, buf, os.bytes_written);
    free(buf);
}

void hnd_solar_config_get(coap_resource_t *resource, coap_session_t *session,
                          const coap_pdu_t *request, const coap_string_t *query,
