p='firmware/main/energy/flux_export_cap.c'
s=open(p).read()

s = s.replace("""#include <esp_log.h>
#include <esp_timer.h>""",
"""#include "pb_encode.h"
#include "pb_decode.h"

#include <esp_log.h>
#include <esp_timer.h>
#include <nvs.h>
#include <nvs_flash.h>
#include <freertos/semphr.h>""", 1)

s = s.replace("""static flux_export_cap_state_t s_state;""",
"""static flux_export_cap_state_t s_state;

/* ── configuration ───────────────────────────────────────────────────────────
 *
 * Cached in RAM and consulted every cycle; NVS is touched only on a write. The
 * default is DISABLED: the ceiling is the grid operator's and nothing on the
 * network reports it, so an unconfigured controller must enforce nothing
 * rather than guess a limit and curtail a house it knows nothing about. */
#define NVS_NS       "flux_ess"
#define NVS_KEY_CFG  "cfg"

static flux_EssConfig    s_cfg = flux_EssConfig_init_zero;
static bool              s_cfg_loaded;
static SemaphoreHandle_t s_cfg_lock;

static void cfg_lock_init(void)
{
    if (!s_cfg_lock) s_cfg_lock = xSemaphoreCreateMutex();
}
static void cfg_lock(void)   { cfg_lock_init(); xSemaphoreTake(s_cfg_lock, portMAX_DELAY); }
static void cfg_unlock(void) { xSemaphoreGive(s_cfg_lock); }

/* Fills in what the caller left at zero, so a config that sets only the limit
 * still produces a working policy. */
static void cfg_apply_defaults(flux_EssConfig *c)
{
    if (c->export_margin_w == 0) c->export_margin_w = FLUX_EXPORT_CAP_MARGIN_W;
    if (c->pv_base_limit_w == 0 && c->export_limit_w > 0) {
        /* Without an explicit base, assume the inverter is the only thing
         * feeding in: then the ceiling is exactly what it may make alone. A
         * site with a second feeder (a balcony plant) must say so, because we
         * cannot see it. */
        c->pv_base_limit_w = c->export_limit_w;
    }
}

void flux_export_cap_load_config(void)
{
    cfg_lock();
    if (s_cfg_loaded) { cfg_unlock(); return; }
    s_cfg_loaded = true;

    nvs_handle_t h;
    uint8_t buf[flux_EssConfig_size];
    size_t len = sizeof(buf);
    if (nvs_open(NVS_NS, NVS_READONLY, &h) == ESP_OK) {
        if (nvs_get_blob(h, NVS_KEY_CFG, buf, &len) == ESP_OK) {
            pb_istream_t is = pb_istream_from_buffer(buf, len);
            flux_EssConfig c = flux_EssConfig_init_zero;
            if (pb_decode(&is, flux_EssConfig_fields, &c)) {
                cfg_apply_defaults(&c);
                s_cfg = c;
            }
        }
        nvs_close(h);
    }
    cfg_unlock();

    if (s_cfg.enabled)
        ESP_LOGI(TAG, "config: export %lu W (hold %lu W below), PV base %lu W — %s",
                 (unsigned long)s_cfg.export_limit_w,
                 (unsigned long)s_cfg.export_margin_w,
                 (unsigned long)s_cfg.pv_base_limit_w,
                 s_cfg.basis[0] ? s_cfg.basis : "no basis recorded");
    else
        ESP_LOGI(TAG, "config: disabled — enforcing nothing");
}

esp_err_t flux_export_cap_get_config(flux_EssConfig *out)
{
    if (!out) return ESP_ERR_INVALID_ARG;
    cfg_lock();
    if (!s_cfg_loaded) { cfg_unlock(); flux_export_cap_load_config(); cfg_lock(); }
    *out = s_cfg;
    cfg_unlock();
    return ESP_OK;
}

esp_err_t flux_export_cap_set_config(const flux_EssConfig *cfg)
{
    if (!cfg) return ESP_ERR_INVALID_ARG;

    flux_EssConfig c = *cfg;
    cfg_apply_defaults(&c);

    uint8_t buf[flux_EssConfig_size];
    pb_ostream_t os = pb_ostream_from_buffer(buf, sizeof(buf));
    if (!pb_encode(&os, flux_EssConfig_fields, &c)) return ESP_ERR_INVALID_ARG;

    nvs_handle_t h;
    esp_err_t err = nvs_open(NVS_NS, NVS_READWRITE, &h);
    if (err == ESP_OK) {
        err = nvs_set_blob(h, NVS_KEY_CFG, buf, os.bytes_written);
        if (err == ESP_OK) err = nvs_commit(h);
        nvs_close(h);
    }
    if (err != ESP_OK) return err;

    cfg_lock();
    s_cfg = c;
    s_cfg_loaded = true;
    cfg_unlock();

    ESP_LOGI(TAG, "config set: %s export %lu W (hold %lu below), PV base %lu W",
             c.enabled ? "enabled" : "disabled",
             (unsigned long)c.export_limit_w,
             (unsigned long)c.export_margin_w,
             (unsigned long)c.pv_base_limit_w);
    return ESP_OK;
}""", 1)
open(p,'w').write(s)
print('config persistence added')
PYEOF

