        if (s_state.armed || s_holding_battery) {
            ESP_LOGI(TAG, "no export limit configured — standing down");
            if (battery.found) (void)flux_modbus_task_power_cancel(battery.node_id);
            if (pv.found)      (void)flux_modbus_task_power_cancel(pv.node_id);
            s_holding_battery = false;
            s_batt_setpoint_w = 0;
            s_pv_sent_limit_w = 0;
            s_state.armed     = false;
        }
        s_state.enabled = false;
        return;
    }
    s_state.enabled  = true;
    const int32_t base_w = (int32_t)cfg.pv_base_limit_w;""", 1)

