    } else if (limitW != null) {
      mode = 'Manual';
      tone = const Color(0xFFE0894A);
      detail = 'Held at ${powerLabelW(limitW.toDouble())} by hand. No feed-in '
          'limit is configured, so nothing will adjust it.';
    } else {
      mode = 'Unlimited';
      detail = 'No feed-in limit is set, so nothing is being held back.';
    }

