"""/* Picks the meter the limit is regulated against.
 *
 * A configured node wins outright, so a site with more than one meter can say
 * which represents its connection point. Failing that: a device publishing a
 * system-level grid reading first — it already includes anything feeding in on
 * its own supply — and only then a plain grid meter, which may not. */
static bool grid_candidate(const flux_energy_sample_t *s, uint8_t cls,
                           uint64_t want, bool *is_system)
{
    const bool system_level = s->has_grid_power;
    const bool plain_meter  = (cls == flux_EnergyClass_ENERGY_CLASS_GRID) &&
                              s->has_power;
    if (!system_level && !plain_meter) return false;
    if (want && s->node_id != want) return false;
    *is_system = system_level;
    return true;
}

static void collect(actuator_t *grid, actuator_t *battery, actuator_t *pv,
                    int32_t *other_pv_w, uint64_t want_meter)
{""", 1)

old = """            /* The GX publishes the connection-point grid reading from the
             * system service, which is the battery device here. It is the only
             * meter that already includes the balcony inverter. */
            if (!grid->found && s->has_grid_power) {
                grid->found   = true;
