new = '''// GET /energy/events — why the engine did what it did, newest last.
//
// A decision log rather than a measurement log. The engine acts continuously
// and mostly invisibly: a limit held and a cloud passing produce the same power
// readings, so without this the only way to tell what happened is to infer it
// from curves. Entries are written on TRANSITIONS, not on every cycle.
//
// The controller records what happened and to which device; the words are the
// app's, so phrasing can improve without a firmware flash and no strings are
// kept in flash.
enum EnergyEventKind {
    ENERGY_EVENT_UNSPECIFIED   = 0;
    ENERGY_EVENT_LIMIT_APPLIED = 1;  // began holding a generator at value_w
    ENERGY_EVENT_LIMIT_RAISED  = 2;  // the hold eased — value_w is the new one
    ENERGY_EVENT_LIMIT_CLEARED = 3;  // stopped limiting entirely
    ENERGY_EVENT_ABSORB_START  = 4;  // asked a battery to take value_w
    ENERGY_EVENT_ABSORB_STOP   = 5;  // handed it back to its own mode
    ENERGY_EVENT_BATTERY_FULL  = 6;  // nowhere to put surplus; curtailing instead
    ENERGY_EVENT_BATTERY_STALL = 7;  // accepting setpoints without following them
    ENERGY_EVENT_METER_LOST    = 8;  // fell back to the safe limit
    ENERGY_EVENT_METER_OK      = 9;  // measuring again
    ENERGY_EVENT_CONFIG_SET    = 10; // the limits changed under it
}

message EnergyEvent {
    int64           at      = 1;  // UTC epoch seconds, 0 if the clock was unset
    EnergyEventKind kind    = 2;
    uint64          node_id = 3;  // the device it concerns, 0 = the site
    sint32          value_w = 4;  // the limit or setpoint, where one applies
    sint32          grid_w  = 5;  // what the grid was doing at the time
}

message EnergyEventList { repeated EnergyEvent events = 1; }

'''
