cd /home/tado/workspace/flux/flux-controller && python3 - <<'PYEOF'
import pathlib
p = pathlib.Path('firmware/main/energy/flux_export_cap.h')
s = p.read_text()
s = s.replace("""void flux_export_cap_get(flux_export_cap_state_t *out);""",
"""void flux_export_cap_get(flux_export_cap_state_t *out);

/* The decision log, newest last. Copies at most `max` entries into `out` and
 * returns how many were written. Small and in RAM: it answers "what happened
 * this afternoon", not "what happened last week" — the energy log already
 * keeps the long record, and this keeps the reasons. */
#define FLUX_ENERGY_EVENTS_MAX 32
size_t flux_export_cap_events(flux_EnergyEvent *out, size_t max);

/* Record something the user would want explained. Public so a config write can
 * note itself. */
void flux_export_cap_note(flux_EnergyEventKind kind, uint64_t node_id,
                          int32_t value_w);""", 1)
p.write_text(s)

p2 = pathlib.Path('firmware/main/energy/flux_export_cap.c')
s2 = p2.read_text()
s2 = s2.replace("""static flux_export_cap_state_t s_state;""",
"""static flux_export_cap_state_t s_state;

/* ── decision log ────────────────────────────────────────────────────────────
 *
 * A ring of transitions. Written when something CHANGES, never per cycle: a
 * log that repeated "still limiting" every two seconds would bury the moment it
 * started, which is the only part anyone wants. */
static flux_EnergyEvent  s_events[FLUX_ENERGY_EVENTS_MAX];
static size_t            s_events_n;      /* total ever written */
static SemaphoreHandle_t s_events_lock;

void flux_export_cap_note(flux_EnergyEventKind kind, uint64_t node_id,
                          int32_t value_w)
{
    if (!s_events_lock) s_events_lock = xSemaphoreCreateMutex();
    if (!s_events_lock) return;
    xSemaphoreTake(s_events_lock, portMAX_DELAY);
    flux_EnergyEvent *e = &s_events[s_events_n % FLUX_ENERGY_EVENTS_MAX];
    e->at      = flux_time_is_synced() ? (int64_t)time(NULL) : 0;
    e->kind    = kind;
    e->node_id = node_id;
    e->value_w = value_w;
    e->grid_w  = s_state.grid_w;
    s_events_n++;
    xSemaphoreGive(s_events_lock);
}

size_t flux_export_cap_events(flux_EnergyEvent *out, size_t max)
{
    if (!out || !max || !s_events_lock) return 0;
    xSemaphoreTake(s_events_lock, portMAX_DELAY);
    const size_t have = s_events_n < FLUX_ENERGY_EVENTS_MAX
                      ? s_events_n : FLUX_ENERGY_EVENTS_MAX;
    const size_t want = have < max ? have : max;
    /* Oldest first, so the caller reads it as a story. */
    const size_t first = s_events_n - want;
    for (size_t i = 0; i < want; i++)
        out[i] = s_events[(first + i) % FLUX_ENERGY_EVENTS_MAX];
    xSemaphoreGive(s_events_lock);
    return want;
}""", 1)
s2 = s2.replace('#include <nvs.h>', '#include "flux_time.h"\n\n#include <nvs.h>\n#include <time.h>', 1)
p2.write_text(s2)
print('ring buffer added')
PYEOF
cd /home/tado/workspace/flux/flux-controller && ls firmware/main/*/flux_time.h 2>/dev/null || grep -rn "flux_time_is_synced" firmware/main/ --include=*.h | head -2

