                          : flux_EnergyEventKind_ENERGY_EVENT_BATTERY_STALL,
                battery.node_id, battery.power_w);
            (void)flux_modbus_task_power_cancel(battery.node_id);
            s_holding_battery = false;
            s_batt_setpoint_w = 0;""", 1)

