            flux_export_cap_note(flux_EnergyEventKind_ENERGY_EVENT_LIMIT_RAISED,
                                 pv.node_id, limit_w);
        send_pv_limit(pv.node_id, limit_w, now_us);
        s_state.pv_limit_w = limit_w;
        s_state.curtailing = pinned;
    }

    /* What the house is running on. Mostly somebody else's doing, and recorded
     * because a log of only our own choices would read as though nothing else
     * happened all day. Hysteresis is crude on purpose: this is a headline, and
     * a headline that changes every minute is noise. */
    {
        const int32_t pv_w   = pv.found ? pv.power_w : 0;
        const int32_t batt_w = battery.found ? battery.power_w : 0;
        flux_EnergyEventKind on;
        if (grid.power_w > 300)      on = flux_EnergyEventKind_ENERGY_EVENT_HOUSE_ON_GRID;
        else if (batt_w < -300)      on = flux_EnergyEventKind_ENERGY_EVENT_HOUSE_ON_BATTERY;
        else if (pv_w > 300)         on = flux_EnergyEventKind_ENERGY_EVENT_HOUSE_ON_SOLAR;
        else                         on = flux_EnergyEventKind_ENERGY_EVENT_UNSPECIFIED;

        static flux_EnergyEventKind s_on;
        static uint8_t              s_on_streak;
