            /* Must hold for a while: a kettle must not rewrite the day. */
            if (++s_on_streak >= 15) {
                s_on = on;
                s_on_streak = 0;
                flux_export_cap_note(on, 0, grid.power_w);
            }
        } else {
            s_on_streak = 0;
        }""", 1)
p.write_text(s)
print('transitions recorded')
