import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';
import 'package:matter_home/models/home_category.dart';

/// Apple-Home-style row of category buttons shown under the app title. Each is
/// a black pill with a pastel outline and text in the category's accent colour;
/// tapping opens that category's screen.
///
/// The row scrolls rather than dividing the width evenly. Four categories
/// already squeezed the labels, and a fifth would squeeze them further — a
/// button that has to shrink to fit is a button that will eventually be
/// unreadable, so they keep their size and the row moves instead.
class CategoryBar extends StatelessWidget {
  const CategoryBar({super.key});

  @override
  Widget build(BuildContext context) {
    return SingleChildScrollView(
      scrollDirection: Axis.horizontal,
      // Padding inside the scroll view, so the first and last buttons line up
      // with the cards below at rest and can still scroll clear of the edge.
      padding: const EdgeInsets.fromLTRB(16, 8, 16, 4),
      child: Row(
        children: [
          for (var i = 0; i < HomeCategory.values.length; i++) ...[
            if (i > 0) const SizedBox(width: 10),
            _CategoryButton(category: HomeCategory.values[i]),
          ],
        ],
      ),
    );
  }
}

class _CategoryButton extends StatelessWidget {
  const _CategoryButton({required this.category});
  final HomeCategory category;

  @override
  Widget build(BuildContext context) {
    final color = category.color;
    return Material(
      color: Colors.black,
      clipBehavior: Clip.antiAlias,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(16),
        side: BorderSide(color: color, width: 1.5),
      ),
      child: InkWell(
        onTap: () => context.push('/category/${category.name}'),
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 12, horizontal: 16),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(category.icon, color: color, size: 18),
              const SizedBox(width: 6),
              Text(
                category.label,
                style: TextStyle(
                  color: color,
                  fontWeight: FontWeight.w600,
                  fontSize: 13.5,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:matter_home/models/device_type.dart';
import 'package:matter_home/models/device_view.dart';
import 'package:matter_home/models/energy_role.dart';

/// A top-level grouping surfaced as a button row on the home screen (à la Apple
/// Home). Each opens its own [CategoryScreen] — Energy hosts the live
/// energy-flow overview, the others a filtered device grid.
enum HomeCategory {
  energy,
  lighting,
  climate,
  /// Everything the others do not claim — a plug that only switches, a lock, a
  /// button, a sensor with no home elsewhere.
  ///
  /// It exists so the home screen does not have to be a list of leftovers. This
  /// app is about energy; a device that has nothing to do with energy, light or
  /// comfort still has to live somewhere, and somewhere is not the first thing
  /// you see.
  other;

  String get label => switch (this) {
        HomeCategory.energy   => 'Energy',
        HomeCategory.lighting => 'Lighting',
        HomeCategory.climate  => 'Climate',
        HomeCategory.other    => 'Other',
      };

  IconData get icon => switch (this) {
        HomeCategory.energy   => Icons.bolt_outlined,
        HomeCategory.lighting => Icons.lightbulb_outline,
        HomeCategory.climate  => Icons.thermostat_outlined,
        HomeCategory.other    => Icons.widgets_outlined,
      };

  /// Pastel accent for the button outline + text and the category screen title.
  Color get color => switch (this) {
        HomeCategory.energy   => const Color(0xFFE8D66B), // pastel yellow
        HomeCategory.lighting => const Color(0xFFF2B877), // pastel orange
        HomeCategory.climate  => const Color(0xFF8FCDEF), // pastel blue
        HomeCategory.other    => const Color(0xFFB9B6C9), // pastel grey-violet
      };

  /// Whether this category's devices are listed room by room, with the room's
  /// shared controls above each set.
  ///
  /// Lighting, because "everything in here" is a thing people act on and the
  /// controls mean the same across a room. Other, because it is a miscellany
  /// and the only order anyone has for a miscellany is where things are.
  ///
  /// Energy is a dashboard, not a set of controls; Climate wants a room
  /// setpoint rather than a room slider, and gets this once it has one.
  bool get groupsByRoom =>
      this == HomeCategory.lighting || this == HomeCategory.other;

  /// Whether [v] belongs in this category's device grid.
  bool matches(DeviceView v) => switch (this) {
        HomeCategory.energy => v.energyRole != EnergyRole.none ||
            v.deviceType.hasEnergyMeasurement ||
            v.hasLivePower,
        HomeCategory.lighting => v.deviceType.isLight,
        HomeCategory.climate => switch (v.deviceType) {
            DeviceType.thermostat ||
            DeviceType.fan ||
            DeviceType.airPurifier ||
            DeviceType.temperatureSensor ||
            DeviceType.humiditySensor ||
            DeviceType.airQualitySensor => true,
            _ => false,
          },
        // Defined by exclusion, so a device is never in two places at once and
        // a new category automatically empties this one of whatever it claims.
        HomeCategory.other => !_claimed(v),
      };

  static bool _claimed(DeviceView v) =>
      HomeCategory.energy.matches(v) ||
      HomeCategory.lighting.matches(v) ||
      HomeCategory.climate.matches(v);
}

part of '../device_detail_screen.dart';

/// What is limiting this inverter, and to what. Read-only on purpose.
///
/// The limit is not a per-device setting any more: it follows from the grid
/// connection's feed-in limit, which the controller enforces continuously. A
/// slider here would be overwritten within a cycle — the engine re-asserts the
/// setpoint every couple of seconds — so offering one would be offering a
/// control that does not work.
///
/// What is worth showing is the consequence, because it is otherwise invisible:
/// an inverter held at 10.8 kW and an inverter under a cloud produce the same
/// reading, and only the controller knows which this is.
class PvLimitCard extends StatefulWidget {
  const PvLimitCard({required this.adjust, super.key});

  final PowerAdjust adjust;

  @override
  State<PvLimitCard> createState() => _PvLimitCardState();
}

class _PvLimitCardState extends State<PvLimitCard> {
  @override
  void initState() {
    super.initState();
    // Without this the card cannot tell automatic from manual: the engine's
    // state is fetched on demand, and a screen that never asks sees null and
    // would report a managed limit as something someone set by hand.
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) context.read<DeviceProvider>().fetchEnergyControl();
    });
  }

  @override
  Widget build(BuildContext context) {
    final adjust = widget.adjust;
    final cs = Theme.of(context).colorScheme;
    final p = context.watch<DeviceProvider>();
    final ctrl = p.energyControl;
    final managed = ctrl != null && ctrl.enabled;

    // The device's own hold is the authority on the number: it is what the
    // inverter was actually told, whoever told it.
    final heldMw = adjust.isActive ? adjust.activePowerMw : null;
    final limitW = heldMw != null ? (heldMw.abs() / 1000).round() : null;

    final String mode;
    final String detail;
    Color tone = cs.onSurfaceVariant;

    if (managed) {
      // Automatic even when nothing is being held back: the controller is
      // watching and will move the limit the moment the roof beats the grid's
      // ceiling. A number that is adjusted for you is not a manual setting.
      mode = 'Automatic';
      if (limitW == null) {
        detail = 'Running unrestricted. The controller will step in if the '
            'roof makes more than the grid will take.';
      } else if (ctrl.curtailing) {
        tone = const Color(0xFFE8C14A);
        detail = 'Limited to ${powerLabelW(limitW.toDouble())} — this is '
            'costing production right now.';
      } else {
        tone = Theme.of(context).colorScheme.primary;
        detail = 'Limited to ${powerLabelW(limitW.toDouble())}. The roof is '
            'not making that much, so nothing is being lost.';
      }
    } else if (limitW != null) {
      mode = 'Manual';
      tone = const Color(0xFFE0894A);
      detail = 'Held at ${powerLabelW(limitW.toDouble())} by hand. No feed-in '
          'limit is configured, so nothing will adjust it.';
    } else {
      mode = 'Not capped';
      detail = 'No feed-in limit is set, so nothing is being held back.';
    }

    return Card(
      margin: EdgeInsets.zero,
      child: Padding(
        padding: const EdgeInsets.fromLTRB(14, 13, 14, 10),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Icon(Icons.solar_power_outlined,
                    size: 18, color: cs.onSurfaceVariant),
                const SizedBox(width: 8),
                Text('Output control',
                    style: Theme.of(context).textTheme.titleSmall),
                const Spacer(),
                Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 9, vertical: 3),
                  decoration: BoxDecoration(
                    borderRadius: BorderRadius.circular(999),
                    border: Border.all(color: tone.withValues(alpha: 0.5)),
                    color: tone.withValues(alpha: 0.12),
                  ),
                  child: Text(mode,
                      style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w600,
                          color: tone)),
                ),
                IconButton(
                  visualDensity: VisualDensity.compact,
                  tooltip: 'Energy management',
                  icon: Icon(Icons.tune, size: 18, color: cs.onSurfaceVariant),
                  onPressed: () => Navigator.of(context).push(
                    MaterialPageRoute<void>(
                        builder: (_) => const GridSettingsScreen()),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 6),
            Text(detail,
                style: TextStyle(
                    fontSize: 13.5, height: 1.35, color: cs.onSurfaceVariant)),
            const SizedBox(height: 4),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:provider/provider.dart';

import 'package:fixnum/fixnum.dart' as $fixnum;
import 'package:matter_home/models/device_view.dart';
import 'package:matter_home/models/energy_role.dart';
import 'package:matter_home/providers/device_provider.dart';
import 'package:matter_home/services/hub_connection.dart';
import 'package:matter_home/services/proto/flux.pb.dart' as $proto;

/// What the grid connection allows: the EEG §9 feed-in limit, and whether the
/// controller holds the house inside it.
///
/// The limit is the one number in the energy system that nothing on the network
/// reports: it comes from the grid operator. It lives on the controller because
/// the controller is what enforces it — a limit held only on a phone stops
/// existing when the phone does, which is exactly when it still has to hold.
///
/// The screen carries the reasoning as well as the number. A regulatory limit
/// outlives the memory of why it was set, and a year from now the difference
/// between a rule that still applies and one that expired is the note someone
/// wrote at the time.
///
/// Writes are LAN-only on the controller (flux-proto ADR-0012), so the save
/// button is disabled over a remote tunnel rather than failing after the fact.
class GridSettingsScreen extends StatefulWidget {
  const GridSettingsScreen({super.key});

  @override
  State<GridSettingsScreen> createState() => _GridSettingsScreenState();
}

class _GridSettingsScreenState extends State<GridSettingsScreen> {
  final _limit = TextEditingController();
  /// 0 = let the controller choose.
  $fixnum.Int64 _meter = $fixnum.Int64.ZERO;

  bool _enabled = false;
  bool _loaded = false;
  bool _saving = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      final p = context.read<DeviceProvider>();
      final cfg = await p.fetchEnergyLimits();
      await p.fetchEnergyControl();
      if (!mounted || cfg == null) return;
      setState(() {
        _enabled = cfg.enabled;
        _limit.text = cfg.exportLimitW == 0 ? '' : cfg.exportLimitW.toString();
        _meter = cfg.meterNodeId;
        _loaded = true;
      });
    });
  }

  @override
  void dispose() {
    _limit.dispose();
    super.dispose();
  }

  int? _int(TextEditingController c) => int.tryParse(c.text.trim());

  Future<void> _save() async {
    final limit = _int(_limit);
    if (_enabled && (limit == null || limit <= 0)) {
      _snack('Enter the limit your grid operator allows');
      return;
    }
    final p = context.read<DeviceProvider>();
    final cfg = p.energyLimits?.deepCopy() ?? $proto.EnergyLimits();
    // Margin and the inverter's unaided limit are left at zero on purpose: the
    // controller fills in its own default for the first and measures the second
    // from whatever else feeds in. Neither is a number a person should maintain.
    cfg
      ..enabled = _enabled
      ..exportLimitW = limit ?? 0
      ..exportMarginW = 0
      ..pvBaseLimitW = 0
      ..meterNodeId = _meter;

    setState(() => _saving = true);
    final ok = await p.updateEnergyLimits(cfg);
    if (!mounted) return;
    setState(() => _saving = false);
    _snack(ok ? 'Grid limits saved' : "Couldn't save — on the local network?");
    if (ok) Navigator.of(context).pop();
  }

  void _snack(String m) =>
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(m)));

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    final tt = Theme.of(context).textTheme;
    final hub = context.watch<HubConnection>();
    final p = context.watch<DeviceProvider>();
    final canWrite = hub.connectionKind == ConnectionKind.local;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Energy Management',
            style: TextStyle(fontWeight: FontWeight.bold)),
      ),
      body: ListView(
        padding: const EdgeInsets.all(16),
        children: [
          SwitchListTile(
            contentPadding: EdgeInsets.zero,
            value: _enabled,
            onChanged: _loaded ? (v) => setState(() => _enabled = v) : null,
            title: const Text('Feed-in limit'),
            subtitle: Text(
                'Off means the controller enforces nothing.',
                style: TextStyle(color: cs.onSurfaceVariant)),
          ),
          const SizedBox(height: 12),
          TextField(
            controller: _limit,
            enabled: _enabled,
            keyboardType: TextInputType.number,
            inputFormatters: [FilteringTextInputFormatter.allow(RegExp('[0-9]'))],
            decoration: const InputDecoration(
              labelText: 'Limit',
              hintText: '11600',
              suffixText: 'W',
              border: OutlineInputBorder(),
            ),
          ),
          const SizedBox(height: 8),
          Text('EEG §9 limit.',
              style: tt.bodySmall?.copyWith(color: cs.onSurfaceVariant)),
          const SizedBox(height: 22),

          DropdownButtonFormField<$fixnum.Int64>(
            initialValue: _meter,
            decoration: const InputDecoration(
              labelText: 'Measured at',
              border: OutlineInputBorder(),
            ),
            items: [
              DropdownMenuItem(
                  value: $fixnum.Int64.ZERO,
                  child: const Text('Choose automatically')),
              for (final d in _meterChoices(p))
                DropdownMenuItem(
                    value: $fixnum.Int64(d.nodeId), child: Text(d.name)),
            ],
            onChanged: _enabled
                ? (v) => setState(() => _meter = v ?? $fixnum.Int64.ZERO)
                : null,
          ),
          const SizedBox(height: 8),
          Text(
            'The limit applies at the grid connection, so this has to be a '
            'meter that sees everything feeding in — including anything on its '
            'own supply.',
            style: tt.bodySmall?.copyWith(color: cs.onSurfaceVariant),
          ),
          const SizedBox(height: 18),

          if (p.energyControl != null) _Cadence(state: p.energyControl!),
          const SizedBox(height: 18),

          if (!canWrite)
            Padding(
              padding: const EdgeInsets.only(bottom: 12),
              child: Text(
                hub.isOnline
                    ? 'Connected remotely — this can only be changed on your '
                      'home network.'
                    : 'Controller unreachable.',
                style: tt.bodySmall?.copyWith(color: cs.error),
              ),
            ),
          FilledButton(
            onPressed: (_saving || !canWrite || !_loaded) ? null : _save,
            child: Text(_saving ? 'Saving…' : 'Save'),
          ),
        ],
      ),
    );
  }
}

/// Candidate meters: anything the controller could regulate against. A device
/// publishing a system-level grid reading qualifies whatever its own role, which
/// is how a battery inverter's system service ends up in this list.
List<DeviceView> _meterChoices(DeviceProvider p) => [
      for (final d in p.deviceViews)
        if (d.energyRole == EnergyRole.grid ||
            (d.live?.attrs.containsKey('gridActivePower') ?? false))
          d,
    ];

/// How often the loop runs, and against which meter — read-only, because both
/// are the engine's own doing rather than anything to choose.
class _Cadence extends StatelessWidget {
  const _Cadence({required this.state});
  final $proto.EnergyControl state;

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    final ms = state.intervalMs;
    final every = ms >= 1000
        ? '${(ms / 1000).toStringAsFixed(ms % 1000 == 0 ? 0 : 1)} s'
        : '$ms ms';
    return Row(
      children: [
        Icon(Icons.update, size: 15, color: cs.onSurfaceVariant),
        const SizedBox(width: 8),
        Expanded(
          child: Text(
            state.armed
                ? 'Checked every $every.'
                : 'Checked every $every — not reading a meter yet.',
            style: TextStyle(fontSize: 12.5, color: cs.onSurfaceVariant),
          ),
        ),
      ],
    );
  }
}

#pragma once

#include "flux.pb.h"

#include <esp_err.h>
#include <stdbool.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

/*
 * flux_export_cap — hold grid export below the connection point's limit.
 *
 * The first module of the ESS engine described in FW-ADR-0019, and deliberately
 * the smallest useful one: it binds to whatever advertises the capability it
 * needs and does nothing when a house lacks the parts.
 *
 * What it does, every FLUX_EXPORT_CAP_PERIOD_MS:
 *
 *   1. Read grid power at the connection point. Export over the limit is the
 *      error to remove.
 *   2. Ask the battery to absorb the excess — the energy is worth more stored
 *      than discarded, and this is the only lever that loses nothing.
 *   3. Allow the PV inverter to produce above the safe limit by exactly what
 *      the battery is MEASURED to be absorbing, never by what it was asked to
 *      absorb. Curtailment is what is left when the battery cannot keep up.
 *
 * Why the elevation tracks measured absorption
 * --------------------------------------------
 * A dynamic cap cannot guarantee compliance by itself: to capture the clipped
 * energy the inverter must be allowed above the limit, and a controller that
 * dies at that moment leaves it there. SunSpec's revert timer is no help — it
 * reverts to UNLIMITED, which is the unsafe direction here.
 *
 * So the elevation is bounded by something that decays on its own. The inverter
 * may exceed the safe limit only by the power the battery is actually taking,
 * and the battery's hold expires by itself shortly after the controller stops
 * refreshing it. A hard crash therefore overshoots by at most the battery's
 * charge power, for at most the life of its hold — not indefinitely, and not by
 * the inverter's full output.
 *
 * House load is deliberately NOT counted as headroom. It is real while it
 * lasts, but a kettle switching off removes kilowatts between two samples, and
 * a limit that depends on a load staying on is not a limit.
 */

/* Defaults, used when nothing has been configured. They are compiled in only
 * so a controller with no config still behaves sanely; the live values come
 * from EnergyLimits, which the app writes and NVS keeps.
 *
 * The ceiling is the grid operator's, which nothing on the network reports —
 * so an unconfigured controller enforces NOTHING (enabled defaults false)
 * rather than guessing a limit and curtailing a house it knows nothing about. */
#define FLUX_EXPORT_CAP_W        11600   /* 60 % of 18 kWp + 800 W balcony */
#define FLUX_EXPORT_CAP_BASE_W   10800
#define FLUX_EXPORT_CAP_MARGIN_W   200

#define FLUX_EXPORT_CAP_PERIOD_MS 2000

/* Start the module. Safe to call when the house has none of the parts: it
 * reports what is missing and stays dormant rather than failing. */
esp_err_t flux_export_cap_start(void);

/* The configured limits. Reads are cheap: the struct is cached in RAM and NVS
 * is touched only on a write. */
esp_err_t flux_export_cap_get_config(flux_EnergyLimits *out);

/* Persist and apply. Takes effect on the next cycle; no restart. */
esp_err_t flux_export_cap_set_config(const flux_EnergyLimits *cfg);

/* Load the persisted config. Call once at startup, before the task runs, from
 * a task with room for an NVS blob read. */
void flux_export_cap_load_config(void);

/* Snapshot for diagnostics / the app. */
typedef struct {
    bool     running;        /* task alive */
    bool     enabled;        /* a limit is configured */
    bool     armed;          /* a usable grid reading and at least one actuator */
    int32_t  grid_w;         /* last reading, + = importing */
    uint64_t meter_node_id;  /* which meter it came from */
    int32_t  export_w;       /* 0 when importing */
    int32_t  battery_target_w;
    int32_t  battery_actual_w;
    int32_t  pv_limit_w;     /* what the inverter is currently allowed */
    int32_t  pv_base_w;      /* what it may make unaided, after other feeders */
    bool     curtailing;     /* pv_limit_w held below what the sun could give */
    uint64_t battery_node_id;/* the absorber in use, 0 = none bound */
    /* Why the battery is not absorbing, when it is not. Full is a limitation;
     * stalled — accepting setpoints without following them — is a fault. */
    bool     battery_full;
    bool     battery_stalled;
    uint32_t faults;         /* times the module fell back to the safe limit */
} flux_export_cap_state_t;

void flux_export_cap_get(flux_export_cap_state_t *out);

/* The decision log, newest last. Copies at most `max` entries into `out` and
 * returns how many were written. Small and in RAM: it answers "what happened
 * this afternoon", not "what happened last week" — the energy log already
 * keeps the long record, and this keeps the reasons. */
#define FLUX_ENERGY_EVENTS_MAX 32
size_t flux_export_cap_events(flux_EnergyEvent *out, size_t max);

/* Record something the user would want explained. Public so a config write can
 * note itself. */
void flux_export_cap_note(flux_EnergyEventKind kind, uint64_t node_id,
                          int32_t value_w);

#ifdef __cplusplus
}
#endif

