message EnergyBucket {
    uint32 index          = 1;  // bucket index relative to EnergyHistory.start
    uint32 grid_import_wh = 2;  // consumed from utility  (OBIS 1.8.0 delta)
    uint32 grid_export_wh = 3;  // fed to utility         (OBIS 2.8.0 delta)
    uint32 pv_wh          = 4;  // PV generated
    uint32 load_wh        = 5;  // load consumed
    uint32 battery_charge_wh    = 6;  // energy stored into a battery (charge)
    uint32 battery_discharge_wh = 7;  // energy drawn from a battery  (discharge)
