static void process_row(dev_state_t *devs, int *n_devs, flux_EnergyHistory *out,
                        bool want_series,
                        uint64_t node_id, int cls, const char *name,
                        const role_cls_t *roles, uint8_t n_roles, int b,
                        int64_t ts, int gap_secs,
                        bool has_imp, int64_t imp, bool has_exp, int64_t exp,
                        bool has_soc, int soc,
                        bool has_pwr, int64_t pwr_mw)
{
    dev_state_t *d = dev_get(devs, n_devs, node_id, cls);
    if (!d) return;

    /* Does this device carry an ASSIGNED energy role today? If so it outranks the
     * class frozen into the archived rows, so history re-reads corrected rather
     * than replaying an old misclassification (see role_cls_snapshot). Looked up
     * once per device per query. */
    if (!d->cls_resolved) {
        d->cls_override = role_cls_lookup(roles, n_roles, node_id);
        d->cls_resolved = true;
    }

    /* A device can be reclassified mid-window (the app changes its energy role,
     * e.g. a plug retagged from load to PV); route by the latest class, not the
     * first-seen one, so the change takes effect within the window. */
    d->cls = d->cls_override ? d->cls_override : cls;

    /* Break PV out per inverter (bounded); allocated the first time the device
     * is seen as PV. The summed buckets are unchanged. */
    if (want_series && cls == CLS_PV && d->series_idx < 0 &&
        out->device_series_count < ENERGY_MAX_SERIES) {
        int k = out->device_series_count++;
        flux_EnergyDeviceSeries *s = &out->device_series[k];
        s->node_id  = node_id;
        s->cls      = flux_EnergyClass_ENERGY_CLASS_PV;
        strlcpy(s->name, name ? name : "", sizeof(s->name));
        s->wh_count = out->buckets_count;  /* dense; wh[] zeroed by calloc */
        d->series_idx = k;
    }

    /* Battery SOC line (measured level). Created the first time a battery device
     * is seen; soc_pct[] starts all-NODATA and is filled per bucket below with
     * the end-of-bucket sample, then carry-forwarded after the pass. */
    if (want_series && cls == CLS_BATTERY && d->soc_series_idx < 0 &&
        out->battery_soc_count < ENERGY_MAX_SOC_SERIES) {
        int k = out->battery_soc_count++;
        flux_BatterySocSeries *s = &out->battery_soc[k];
        s->node_id = node_id;
        strlcpy(s->name, name ? name : "", sizeof(s->name));
        s->soc_pct.size = out->buckets_count;
        for (uint32_t j = 0; j < s->soc_pct.size; j++) s->soc_pct.bytes[j] = ENERGY_SOC_NODATA;
        d->soc_series_idx = k;
    }

    /* End-of-bucket SOC: last sample in bucket b wins (independent of the
     * counter-diff bucket machinery — SOC is a level, not a delta). */
    if (d->soc_series_idx >= 0 && has_soc && b >= 0 &&
        b < (int)out->battery_soc[d->soc_series_idx].soc_pct.size) {
        out->battery_soc[d->soc_series_idx].soc_pct.bytes[b] = (uint8_t)soc;
    }

    /* A REPLAYED row: the same non-zero power and the same counter as the row
     * before it.
     *
     * Written when a device had gone away and the controller rewrote its last
     * known values every cycle as though they were fresh. The contradiction is
     * what identifies them: a device genuinely producing power advances its
     * energy counter, and one that is idle reports zero. Power without
     * progress is a recording of the past.
     *
     * Skipping them leaves a real gap in time, so the guard below rebases
     * across it and the counter growth that happened while nobody was looking
     * is dropped instead of landing in whichever bucket the device came back
     * in. Rows already on the card cannot be unwritten; this reads them
     * honestly.
     */
    if (has_pwr && pwr_mw != 0 && d->have_power && pwr_mw == d->last_power_mw &&
        ((has_imp && d->have_import && imp == d->last_import) || !has_imp) &&
        ((has_exp && d->have_export && exp == d->last_export) || !has_exp) &&
        (has_imp || has_exp)) {
        return;
    }
    if (has_pwr) { d->last_power_mw = pwr_mw; d->have_power = true; }

    /* Time since this device last gave us a counter. Bucket arithmetic alone
     * cannot see an outage that is shorter than a bucket but long enough to
     * matter, and — before the snapshot stopped writing stale rows — could not
     * see one at all: rows kept arriving every bucket carrying a frozen counter,
     * so (b - cur_bucket) was always 1 and the gap test below never fired. Age
     * is the honest measure of "we were not watching". */
    const bool counter_row = has_imp || has_exp;
    /* Aged out, or arrived from the past. The clock can step backwards when
     * SNTP corrects it, and a counter diff taken across that step spans an
     * unknown amount of real time — the same hazard as a long gap, so it gets
     * the same answer. */
    const bool aged_out = counter_row && d->last_counter_ts > 0 &&
                          ((ts - d->last_counter_ts) > gap_secs ||
                           ts < d->last_counter_ts);

    if (d->cur_bucket < 0) {                 /* first row for this device */
        d->cur_bucket = b;
        if (has_imp) { d->have_import = true; d->base_import = imp; d->last_import = imp; }
        if (has_exp) { d->have_export = true; d->base_export = exp; d->last_export = exp; }
        if (counter_row) d->last_counter_ts = ts;
        return;
    }
    if (b > d->cur_bucket) {                  /* advanced past the current bucket */
        const bool gap = (b - d->cur_bucket) > 1;
        close_bucket(d, out);                 /* flush energy accrued in the old bucket */
        d->cur_bucket = b;
        if (gap || aged_out) {
            /* A whole bucket had no rows, or this counter is the first after a
             * long silence — with 10 s sampling either is a real outage (a
             * controller reboot, an inverter that stopped answering), not normal
             * jitter. Rebase the baseline to this reading so the counter growth
             * accumulated during the gap isn't dumped into a single bucket as a
             * huge false spike. The (genuinely unknown) energy is dropped. */
            if (has_imp) { d->base_import = imp; d->last_import = imp; }
            if (has_exp) { d->base_export = exp; d->last_export = exp; }
        }
    } else if (aged_out) {
